head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60100.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("nowYear")) { pc.set("nowYear", $c.date.getServerDateTime("yyyy")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — nowYear, viewYear

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_nowYear", fn: function(){ return ((dma_pageContext.get("nowYear") ?? "") === (dma_pageContext.get("viewYear") ?? "")); } }, { id: "if_nowYear_2", fn: function(){ return ((dma_pageContext.get("nowYear") ?? "") !== (dma_pageContext.get("viewYear") ?? "")); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchMenu", fn: function () { return String(String((dma_pageContext.get("searchMenu") ?? ""))); } },
        { childId: "ipt_nowMonth", fn: function () { return String(String((dma_pageContext.get("nowMonth") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const searchForm = $('#searchForm');
    if ("null" !== "") {
        $c.util.getComponent("slc_selYear").setValue('null');
    }
    if ("null" !== "") {
        $c.util.getComponent("ipt_nowMonth").setValue('null');
    }
    if ("null" !== "") {
        $c.util.getComponent('ipt_searchCorpName').setValue("null");
    } else {
        $c.util.getComponent('ipt_searchCorpName').setValue("회사명/코드");
    }
    const p_idx = 'null';
    if (p_idx !== "") {
        if (p_idx < 10) {
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchMenu", "0" + p_idx);
        } else {
            $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchMenu", p_idx);
        }
    } else {
        $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchMenu", "01");
    }
    scwin.fnSwapImage(($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("nowMonth") || ''), '');
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.init();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
