///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/stockschedule.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchInit = function (no) {
    $("#searchForm > #pageIndex").val("1");
    scwin.fnSearchCorpName(no);
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.fnSearch = function (no) {
    const searchForm = $('#searchForm');
    if (($c.util.getComponent("slc_showMonth").getValue() || '') < 10) {
        $c.util.getComponent("ipt_selMonth").setValue("0" + document.searchForm.find('select[name=slc_showMonth]').val());
    } else {
        $c.util.getComponent("ipt_selMonth").setValue(document.searchForm.find('select[name=slc_showMonth]').val());
    }
    let method = "searchTotalCalendar";
    let forward = "searchtotalcalendar";
    if (no === "11") {
        $(document).find('div[id=search]').css("display", "block");
    } else {
        $(document).find('div[id=search]').css("display", "none");
    }
    switch (no) {
        case "01":
        method = "searchTotalCalendar";
        forward = "searchtotalcalendar";
        break;
        case "02":
        method = "searchPaidinCapitalIncrease";
        forward = "searchpaidincapitalincrease";
        break;
        case "03":
        method = "searchFreeIssueNewShares";
        forward = "searchfreeissuenewshares";
        break;
        case "04":
        method = "searchFaceValueChange";
        forward = "searchfacevaluechange";
        break;
        case "05":
        method = "searchStockDividend";
        forward = "searchstockdividend";
        break;
        case "06":
