/**
 * @method
 * @name fnSwapImage
 * @description fn Swap Image 처리
 * @param {*} val val
 * @param {*} type type
 * @returns {void}
 * @hidden N
 */
scwin.fnSwapImage = function (val, type) {
    const searchForm = $('#searchForm');
    let month = "";
    if (type === "click") {
        $c.util.getComponent("rd_periodType").setValue("M");
        $c.util.getComponent("rd_periodType").setValue("D");
        month = val;
    } else {
        month = ($c.util.getComponent("ipt_nowMonth").getValue() || '');
    }
    $c.util.getComponent("slc_showMonth").setValue(month);
    scwin.clearBtnImage();
    scwin.fnMonthActive(month);
    let vDate, vMon, vDay;
    vDate = new Date();
    vDate.setDate(vDate.getDate());
    const curYearMonth = String(vDate.getFullYear()) + "-" + String(vMon);
    if (($c.util.getComponent("slc_selYear").getValue() || '') === String(vDate.getFullYear()) && ($c.util.getComponent("slc_showMonth").getValue() || '') === String(vDate.getMonth() + 1)) {
        if ((vDate.getMonth() + 1) < 10) {
            vMon = "0" + String(vDate.getMonth() + 1);
        } else {
            vMon = String(vDate.getMonth() + 1);
        }
        if (vDate.getDate() < 10) {
            vDay = "0" + String(vDate.getDate());
        } else {
            vDay = String(vDate.getDate());
        }
        document.searchForm.find('input:text[name=selDate]').val(($c.util.getComponent("slc_selYear").getValue() || '') + "-" + String(vMon) + "-" + String(vDay));
    } else {
        if (val < 10) {
            document.searchForm.find('input:text[name=selDate]').val(($c.util.getComponent("slc_selYear").getValue() || '') + "-0" + val + "-01");
        } else {
            document.searchForm.find('input:text[name=selDate]').val(($c.util.getComponent("slc_selYear").getValue() || '') + "-" + val + "-01");
        }
    }
    scwin.fnSearchInit(($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("searchMenu") || ''));
    scwin.fnClassActive(($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("searchMenu") || ''));
};

