    }
};

/**
 * @method
 * @name chkLmtDate
 * @description chk Lmt Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkLmtDate = async function () {
    const dateVal = $("#searchForm").find("input:text[name=selDate]").val();
    if (dateVal.length === 8) {
        if (dateVal.substring(0, 4) < 1999) {
            await $c.win.alert("1999년부터 조회 가능합니다.");
            $("#searchForm").find("input:text[name=selDate]").val("1999-01-01");
            return false;
        }
    }
};

