 * @hidden N
 */
scwin.fnCompanySearch = function (tabIndex, isurCd) {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchCodeType", "number");
    $c.util.getComponent('ipt_searchCorpName').setValue(isurCd);
    if (tabIndex === "01") {
        scwin.fnSearchInit("02");
        scwin.fnClassActive("02");
    } else {
        if (tabIndex === "02") {
            scwin.fnSearchInit("03");
            scwin.fnClassActive("03");
        } else {
            if (tabIndex === "03") {
                scwin.fnSearchInit("04");
                scwin.fnClassActive("04");
            } else {
                if (tabIndex === "04") {
                    scwin.fnSearchInit("06");
                    scwin.fnClassActive("06");
                } else {
                    if (tabIndex === "05" || tabIndex === "11") {
                        scwin.fnSearchInit("07");
                        scwin.fnClassActive("07");
                    } else {
                        if (tabIndex === "07") {
                            scwin.fnSearchInit("08");
                            scwin.fnClassActive("08");
                        } else {
                            if (tabIndex === "08") {
                                scwin.fnSearchInit("10");
                                scwin.fnClassActive("10");
                            } else {
                                if (tabIndex === "09") {
                                    scwin.fnSearchInit("12");
                                    scwin.fnClassActive("12");
                                } else {
                                    if (tabIndex === "12") {
                                        scwin.fnSearchInit("05");
                                        scwin.fnClassActive("05");
                                    } else {
                                        if (tabIndex === "13") {
                                            scwin.fnSearchInit("09");
                                            scwin.fnClassActive("09");
                                        } else {
                                            if (tabIndex === "14") {
                                                scwin.fnSearchInit("11");
                                                scwin.fnClassActive("11");
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

